// narrate.mjs tarafından üretildi; elle düzenlemeyin. Motor: mbrola:tr1
window.VOICE = {"engine":"mbrola:tr1","gain":1.25,"lines":[{"id":"open-title","say":"Önsöz. Gece yarısı dokunulan cam.","at":2.9,"dur":2.973,"marks":[0,1.157]},{"id":"night-elif","say":"Gece yarısı. On altı yaşındaki Elif, elindeki telefonun camına dokunuyor.","at":9.5815,"dur":5.963,"marks":[0,1.558,3.523]},{"id":"night-berk","say":"Yarın matematik sınavı var. Ama asıl korkan Elif değil; sınıf arkadaşı Berk.","at":18.2831,"dur":6.353,"marks":[0,2.491,4.832]},{"id":"night-type","say":"Elif ekrana üç kelime yazıyor: Yarın birlikte çalışalım.","at":26.0154,"dur":4.498,"marks":[0,2.575]},{"id":"night-send","say":"Gönder tuşuna dokunuyor. Saniyenin onda biri geçmeden, mesaj karşı tarafta.","at":33.0662,"dur":6.331,"marks":[0,2.367,4.764]},{"id":"night-simple","say":"Elif için olan biten bundan ibaret: dokundu ve gitti.","at":41.5215,"dur":4.091,"marks":[0,2.775]},{"id":"night-hidden","say":"Oysa o kısacık aralıkta, insanlığın kurduğu en büyük ortak yapıtlardan biri, sessizce çalışıyor.","at":47.6125,"dur":7.446,"marks":[0,2.098,5.874]},{"id":"jr-switch","say":"Camın hemen altında, saniyede milyarlarca kez açılıp kapanan minicik anahtarlar var. Yazılan her harf, yalnızca iki simgeye dönüşüyor: var ve yok.","at":60.4833,"dur":11.823,"marks":[0,1.789,6.696,8.347,11.003]},{"id":"jr-program","say":"Bunların hepsi, bir insanın önceden yazdığı bir programın adımlarını izleyerek oluyor.","at":76.7864,"dur":5.93,"marks":[0,1.536]},{"id":"jr-memory","say":"İleti, önce telefonun belleğinde şekilleniyor.","at":86.2448,"dur":3.618,"marks":[0,0.878]},{"id":"jr-wifi","say":"Sonra görünmez dalgalara binip, evin köşesindeki küçük kutuya ulaşıyor.","at":92.6264,"dur":5.266,"marks":[0,2.364]},{"id":"jr-fiber","say":"Oradan sokağın altındaki ince cam liflere giriyor. Işık olup; şehirleri, ovaları, denizleri aşıyor.","at":101.731,"dur":8.66,"marks":[0,3.963,5.181,6.432,7.441]},{"id":"jr-routers","say":"Yol boyunca onlarca aygıt, tıpkı haritaya bakan bir yolcu gibi, iletinin nereye gideceğine saniyenin binde biri içinde karar veriyor.","at":114.8187,"dur":9.111,"marks":[0,2.022,4.756]},{"id":"jr-db","say":"Bir yerde, bir veri tabanına kaydediliyor.","at":129.0356,"dur":3.136,"marks":[0,1.143]},{"id":"jr-lock","say":"Bir güvenlik katmanı onu şifreliyor; yolda onu kim görürse görsün, yalnızca anlamsız bir karmaşa görüyor.","at":135.1095,"dur":8.044,"marks":[0,2.976,5.44]},{"id":"jr-arrive","say":"Berk’in telefonuna ulaştığında, bu uzun yolculuğun bütün izleri siliniyor.","at":146.9725,"dur":5.295,"marks":[0,2.727]},{"id":"jr-left","say":"Geriye yalnızca, ekranda beliren o küçük ve sıcak cümle kalıyor.","at":155.4079,"dur":4.726,"marks":[0,1.529]},{"id":"jr-course","say":"Bu kurs, işte o silinen izin peşine düşüyor.","at":162.3339,"dur":3.382,"marks":[0,1.058]},{"id":"br-intro","say":"Silvan yakınlarında, Batman Çayı’nın üzerinde, sekiz yüz yılı aşkın süredir ayakta duran bir köprü var: Malabadi.","at":170.2616,"dur":9.131,"marks":[0,1.898,4.212,8.429]},{"id":"br-see","say":"Uzaktan bakan biri, yalnızca koca bir taş kemer görür.","at":184.1832,"dur":4.128,"marks":[0,1.825]},{"id":"br-forces","say":"Oysa kemeri ayakta tutan güç görünmez: taşları birbirine kilitleyen basınç, tepedeki kilit taşının yükü dağıtması, suyun altında yüzyıllardır kıpırdamayan temel.","at":190.4801,"dur":12.205,"marks":[0,3.065,6.004,9.111]},{"id":"br-master","say":"Ustanın asıl hüneri taşı yontmak değil; hangi taşın hangi yükü taşıyacağını bilmektir.","at":205.0939,"dur":6.281,"marks":[0,3.118]},{"id":"br-team","say":"Üstelik bu köprüyü tek bir kişi kurmadı. Taşçısı, kalıpçısı, harççısı, dülgeri, iskele kurucusu; her biri kendi işinin ustasıydı.","at":214.4524,"dur":12.004,"marks":[0,3.4,4.527,5.783,7.06,8.097,9.806]},{"id":"br-harmony","say":"Yapıyı ayakta tutan, ustaların toplamı değil; aralarındaki uyumdur.","at":227.6339,"dur":5.324,"marks":[0,1.777,3.872]},{"id":"br-cross","say":"Ve bir köprünün asıl işi yük taşımak değil, karşıya geçirmektir. İki yakayı birbirine bağlar.","at":235.6739,"dur":7.419,"marks":[0,3.29,5.527]},{"id":"inv-second","say":"Bugün insanlık, benzer bir yapıyı ikinci kez kuruyor. Ama bu kez taştan değil.","at":247.9139,"dur":6.151,"marks":[0,1.442,4.547]},{"id":"inv-parts","say":"Okyanusların dibinden geçen cam liflerle, gökteki uydularla, şehirlerin kıyısındaki veri merkezleriyle; milyarlarca satır yazılımla.","at":257.4001,"dur":10.526,"marks":[0,3.389,5.095,8.599]},{"id":"inv-unseen","say":"Bu yapının ne ayağı görünüyor, ne kemeri.","at":269.7832,"dur":2.974,"marks":[0,2.215]},{"id":"inv-life","say":"Yine de her gün onun içinde yaşıyoruz: sabah çalan alarm, hastanedeki kayıt, kartla ödeme, tarladaki sulama, uçağın rotası. Hepsi onun içinden geçiyor.","at":274.5572,"dur":12.887,"marks":[0,2.884,4.607,6.297,7.591,9.191,10.942]},{"id":"bd-surface","say":"Görünmediği için, çoğumuz ona yalnızca yüzeyden dokunuyoruz. Düğmeye basıyoruz, ışık yanıyor. Uygulamayı açıyoruz, yemek kapıya geliyor.","at":291.431,"dur":11.46,"marks":[0,1.6,5.02,6.614,8.275,9.972]},{"id":"bd-belief","say":"Ve yavaş yavaş şuna inanmaya başlıyoruz: teknoloji, kullanılan bir şeydir.","at":304.8079,"dur":5.966,"marks":[0,3.215,4.386]},{"id":"bd-claim","say":"Bu kurs, bu inancı nazikçe ama kararlılıkla değiştirmek için var. Teknoloji kullanılan bir şey değil; kurulan bir şeydir.","at":312.3864,"dur":9.808,"marks":[0,1.058,5.583,8.437]},{"id":"bd-decide","say":"Ve onu kuranlar, başkalarının ondan nasıl yararlanacağına da en baştan karar verir.","at":324.7233,"dur":5.782,"marks":[0,1.459]},{"id":"ch-split","say":"Okullarda konular çoğu zaman ayrı kutulara konur: bir yanda donanım, bir yanda programlama, bir yanda ağlar, bir yanda tasarım.","at":334.851,"dur":9.972,"marks":[0,3.746,5.345,7.264,8.732]},{"id":"ch-real","say":"Bu ayrım öğrenmeyi kolaylaştırır; ama gerçekte hiçbir teknoloji tek başına ayakta durmaz.","at":347.1925,"dur":6.499,"marks":[0,2.672]},{"id":"ch-links","say":"Veri tabanı olmayan bir uygulama, hafızasız bir zihindir. Ağa bağlanmayan bir veri tabanı, kapısı örülmüş bir kütüphanedir. Güvenliği olmayan bir ağ, kapısı açık bırakılmış bir evdir.","at":356.3818,"dur":14.281,"marks":[0,2.441,4.759,7.124,9.983,11.966]},{"id":"ch-links2","say":"Algoritması olmayan bir güvenlik, düşünmeyen bir bekçidir. Donanımı olmayan bir algoritma, kâğıtta kalmış bir niyettir. Tasarımı olmayan bütün bu güç ise, insana ulaşamaz.","at":373.3741,"dur":13.789,"marks":[0,2.559,5.019,7.416,10.046,12.658]},{"id":"ch-revisit","say":"Bu yüzden bu kursta konular, kopuk adalar gibi işlenmeyecek. Elif’in o gece gönderdiği iletiye, her kapıda yeniden döneceğiz; her seferinde biraz daha derine inerek.","at":389.4433,"dur":12.618,"marks":[0,2.253,4.984,7.681,10.109]},{"id":"ch-whole","say":"Ta ki o tek dokunuşun ardındaki bütün katmanları, aynı anda görene dek. Buna bütüncül bakış diyoruz: parçaları değil, parçalar arasındaki görünmez bağları görmek.","at":405.9079,"dur":12.559,"marks":[0,3.765,5.718,8.078,9.607]},{"id":"who-everyone","say":"Bu yolculuk kimin için? Teknolojinin perde arkasını merak eden herkes için.","at":423.3418,"dur":5.927,"marks":[0,2.361]},{"id":"who-learner","say":"Bilişime yeni adım atıyorsanız, şunu bilin: öğreneceğiniz bazı araçlar, on yıl sonra kullanılmıyor olabilir. Bu korkulacak değil; sevinilecek bir haber.","at":431.4541,"dur":12.483,"marks":[0,2.379,3.754,5.962,8.988,10.923]},{"id":"who-thinking","say":"Çünkü asıl kazanacağınız şey araçlar değil, bir düşünme biçimi: sorunu parçalara ayırmak, kalıpları görmek, çözümü adım adım kurmak, onu başkasına anlatabilmek. Bu beceri hiç eskimez.","at":446.0618,"dur":14.833,"marks":[0,3.362,5.217,7.323,8.878,10.898,13.365]},{"id":"who-side","say":"Bu alan size, bir meslekten önce bir konum sunuyor: ekranın hangi tarafında duracağınızı seçme hakkı.","at":463.3972,"dur":7.744,"marks":[0,1.297,4.31]},{"id":"who-parent","say":"Çocuğunun ekran başında geçirdiği zamandan endişe eden bir veliyseniz: ekranın karşısında olmakla, ekranın arkasında olmak, bambaşka şeylerdir.","at":473.0525,"dur":11.088,"marks":[0,5.098,7.515,9.575]},{"id":"who-two","say":"Bir çocuk, bir uygulamayı saatlerce kullanabilir. Bir başkası ise sorar: bu neden böyle çalışıyor, verim nereye gidiyor, bunu kim, ne amaçla tasarladı? İkinci çocuk, birincinin dünyasını kuran kişidir.","at":486.2818,"dur":17.418,"marks":[0,1.131,4.29,6.355,8.509,10.284,11.423,13.559,14.929]},{"id":"who-all","say":"Öğretmen, yönetici ya da yalnızca meraklı bir yetişkin olun; bugün üretimden sağlığa, tarımdan hukuka, her alan yazılımla yeniden kuruluyor. Bu dönüşümü anlamak, artık hepimizin işi.","at":506.4879,"dur":14.771,"marks":[0,1.157,4.842,6.896,8.521,11.606,13.293]},{"id":"cr-old","say":"Bu topraklarda bir zanaatı öğrenmenin, çok eski ve bilge bir düzeni vardır.","at":525.3464,"dur":5.319,"marks":[0,2.836]},{"id":"cr-cirak","say":"Çırak izler: bakmayı, tezgâhı temiz bırakmayı, sabretmeyi öğrenir.","at":533.6587,"dur":5.9,"marks":[0,1.49,2.542,4.519]},{"id":"cr-kalfa","say":"Kalfa yapar: ustanın gözü üzerindeyken üretir, hata yapar, hatasından döner.","at":540.9648,"dur":6.534,"marks":[0,1.425,4.002,5.231]},{"id":"cr-usta","say":"Usta ise yalnızca üretmez: öğretir, sorumluluk taşır, yaptığı işin arkasında durur.","at":549.0402,"dur":6.955,"marks":[0,2.172,3.189,4.935]},{"id":"cr-ahi","say":"Bu düzenin adı Ahilikti. En dikkat çekici yanı da şuydu: usta, çırağına önce sanatını değil, ahlakını öğretirdi.","at":557.6541,"dur":9.46,"marks":[0,2.206,4.939,5.792,8.095]},{"id":"cr-today","say":"Bugünün atölyesinde tezgâhın yerini bilgisayar, eğenin yerini kod düzenleyici aldı. Ama düzen aynı: önce başkasının kodunu okursunuz, sonra küçük bir parçasını yazarsınız, en sonunda bir bütünün sorumluluğunu taşırsınız.","at":569.1141,"dur":16.642,"marks":[0,3.482,6.379,7.884,10.561,13.595]},{"id":"cr-ethics","say":"Bu yüzden bu kursta etik, ayrı bir başlığa kapatılmayacak. Bir sistemi nasıl kuracağımızı konuşurken, neden öyle kurmamız gerektiğini de konuşacağız. Bir veriyi saklarken, onun bir insana ait olduğunu unutmayacağız.","at":589.7525,"dur":16.261,"marks":[0,1.958,4.76,8.081,11.813,13.74]},{"id":"cr-motto","say":"Çünkü yeteneğin karakterden hızlı büyüdüğü her yerde, tehlike vardır.","at":609.2064,"dur":5.086,"marks":[0,3.983]},{"id":"st-masons","say":"Bir köprüyü ören taş ustalarının çoğu, karşı yakaya ilk geçen kişiyi göremeden öldü. Yine de her biri kendi taşını, tamamını hiç göremeyeceği bir bütünün parçası olacağını bilerek yonttu.","at":619.2572,"dur":13.687,"marks":[0,2.971,6.765,9.124]},{"id":"st-today","say":"Bugün bilişime adım atan herkes, aynı yapının içinde. Yazılan birkaç satır kod, tasarlanan tek bir ekran, kurulan küçük bir ağ; tek başına küçük görünür.","at":637.471,"dur":12.898,"marks":[0,2.595,4.662,6.936,9.109,11.072]},{"id":"st-bridge","say":"Oysa hepsi, insanlığın kurmakta olduğu o görünmez köprünün, birer taşıdır.","at":652.1556,"dur":5.802,"marks":[0,1.29,4.747]},{"id":"st-welcome","say":"Bu kurs, kendi taşını yontmadan önce, bütünü bir kez olsun görmek isteyenler için. Hoş geldiniz.","at":660.9341,"dur":8.033,"marks":[0,1.058,3.362,7.045]},{"id":"st-next","say":"İlk kapıda, en küçük taşla başlıyoruz: var ve yok.","at":672.1479,"dur":4.579,"marks":[0,1.3,3.758]}],"audio":""};
